// 스프라이트 원본: 사용자가 제공한 Piskel 픽셀아트 4종.
// file:// 로 바로 열어도 동작하도록 base64 data URI 로 내장했습니다.
// (동일한 PNG 원본이 /assets 폴더에도 들어 있습니다.)
const ASSET_SRC = {
  pig: 'data:image/png;base64,',
  mushroom: 'data:image/png;base64,',
  eye: 'data:image/png;base64,',
  brick: 'data:image/png;base64,',
};

const IMG = {};
function loadAssets() {
  const keys = Object.keys(ASSET_SRC);
  return Promise.all(keys.map(k => new Promise(res => {
    const im = new Image();
    im.onload = () => { IMG[k] = im; res(); };
    im.onerror = () => { IMG[k] = null; res(); };
    im.src = ASSET_SRC[k];
  })));
}
